mapper.select:
select 

from MST_EXCHARGE_QUOTE
where EXCHARGE_CODE = #{exchargeCode,jdbcType=VARCHAR}
  and TRADE_DATE = #{tradeDate,jdbcType=TIMESTAMP}

mapper.delete:
delete from MST_EXCHARGE_QUOTE
where EXCHARGE_CODE = #{exchargeCode,jdbcType=VARCHAR}
  and TRADE_DATE = #{tradeDate,jdbcType=TIMESTAMP}

mapper.insert:
insert into MST_EXCHARGE_QUOTE(EXCHARGE_CODE, TRADE_DATE, DATASOURCE_TYPE, OPEN_PRICE, CLOSE_PRICE, HIGH_PRICE, LOW_PRICE, MID_PRICE, BASIS_CYY, QUOT_CYY, QUOT_UNIT, INPUT_TYPE, CREATE_USER, CREATE_DEPT, CREATE_TIME, UPDATE_USER, UPDATE_TIME) select EXCHARGE_CODE, TRADE_DATE, DATASOURCE_TYPE, OPEN_PRICE, CLOSE_PRICE, HIGH_PRICE, LOW_PRICE, MID_PRICE, BASIS_CYY, QUOT_CYY, QUOT_UNIT, INPUT_TYPE, CREATE_USER, CREATE_DEPT, CREATE_TIME, UPDATE_USER, UPDATE_TIME from ( select TEMP.* from (
SELECT #{item.exchargeCode,jdbcType=VARCHAR} EXCHARGE_CODE, #{item.tradeDate,jdbcType=TIMESTAMP} TRADE_DATE, #{item.datasourceType,jdbcType=VARCHAR} DATASOURCE_TYPE, #{item.openPrice,jdbcType=DECIMAL} OPEN_PRICE, #{item.closePrice,jdbcType=DECIMAL} CLOSE_PRICE, #{item.highPrice,jdbcType=DECIMAL} HIGH_PRICE, #{item.lowPrice,jdbcType=DECIMAL} LOW_PRICE, #{item.midPrice,jdbcType=DECIMAL} MID_PRICE, #{item.basisCyy,jdbcType=VARCHAR} BASIS_CYY, #{item.quotCyy,jdbcType=VARCHAR} QUOT_CYY, #{item.quotUnit,jdbcType=DECIMAL} QUOT_UNIT, #{item.inputType,jdbcType=VARCHAR} INPUT_TYPE, #{item.createUser,jdbcType=VARCHAR} CREATE_USER, #{item.createDept,jdbcType=VARCHAR} CREATE_DEPT, NOW() CREATE_TIME, #{item.updateUser,jdbcType=VARCHAR} UPDATE_USER, NOW() UPDATE_TIME FROM DUAL
) TEMP where not exists (select 1 from MST_EXCHARGE_QUOTE CII where CII.EXCHARGE_CODE = TEMP.EXCHARGE_CODE AND CII.TRADE_DATE = TEMP.TRADE_DATE) ) de ;
UPDATE MST_EXCHARGE_QUOTE as A, ( select DATASOURCE_TYPE, OPEN_PRICE, CLOSE_PRICE, HIGH_PRICE, LOW_PRICE, MID_PRICE, BASIS_CYY, QUOT_CYY, QUOT_UNIT, INPUT_TYPE, CREATE_USER, CREATE_DEPT, CREATE_TIME, UPDATE_USER, UPDATE_TIME from ( select TEMP.* from (
SELECT #{item.exchargeCode,jdbcType=VARCHAR} EXCHARGE_CODE, #{item.tradeDate,jdbcType=TIMESTAMP} TRADE_DATE, #{item.datasourceType,jdbcType=VARCHAR} DATASOURCE_TYPE, #{item.openPrice,jdbcType=DECIMAL} OPEN_PRICE, #{item.closePrice,jdbcType=DECIMAL} CLOSE_PRICE, #{item.highPrice,jdbcType=DECIMAL} HIGH_PRICE, #{item.lowPrice,jdbcType=DECIMAL} LOW_PRICE, #{item.midPrice,jdbcType=DECIMAL} MID_PRICE, #{item.basisCyy,jdbcType=VARCHAR} BASIS_CYY, #{item.quotCyy,jdbcType=VARCHAR} QUOT_CYY, #{item.quotUnit,jdbcType=DECIMAL} QUOT_UNIT, #{item.inputType,jdbcType=VARCHAR} INPUT_TYPE, #{item.createUser,jdbcType=VARCHAR} CREATE_USER, #{item.createDept,jdbcType=VARCHAR} CREATE_DEPT, NOW() CREATE_TIME, #{item.updateUser,jdbcType=VARCHAR} UPDATE_USER, NOW() UPDATE_TIME FROM DUAL
) TEMP ) de ) AS B set A.* = B.* where exists (select 1 from MST_EXCHARGE_QUOTE CII where CII.EXCHARGE_CODE = TEMP.EXCHARGE_CODE AND CII.TRADE_DATE = TEMP.TRADE_DATE);
